package main
import ("net/http"; "strings"; "github.com/mattermost/mattermost/server/public/model")
func (p *Plugin) handleTargets(w http.ResponseWriter, r *http.Request){ userID:=userIDFromRequest(r); if userID=="" {writeError(w,http.StatusUnauthorized,"not_authenticated","You must be logged in."); return}; term:=strings.TrimSpace(r.URL.Query().Get("q")); teamID:=strings.TrimSpace(r.URL.Query().Get("team_id")); targets:=[]TargetOption{}; if len(term)>=1 { if teamID!="" { if channels,err:=p.API.SearchChannels(teamID,term); err==nil { for _,ch:=range channels { if ch==nil || ch.DeleteAt!=0 || (ch.Type!=model.ChannelTypeOpen && ch.Type!=model.ChannelTypePrivate){continue}; if p.canPostTarget(userID,ch){ label:="#"+ch.Name; if ch.DisplayName!=""{label="#"+ch.DisplayName}; targets=append(targets,TargetOption{"channel",ch.Id,ch.Name,label}) } } } }; if users,err:=p.API.SearchUsers(&model.UserSearch{Term:term,Limit:20,AllowInactive:false}); err==nil { for _,u:=range users { if u==nil || u.Id==userID || u.DeleteAt!=0 {continue}; targets=append(targets,TargetOption{"user",u.Id,u.Username,"@"+u.Username}) } } }; writeJSON(w,http.StatusOK,map[string]interface{}{"success":true,"targets":targets}) }
